syms=[]  # (pkgdir, pkgname, name, ismethod, file)
for f in gofiles:
    if not f.startswith('./internal/') or f.endswith('_test.go'): continue
    pkgname=re.search(r'^package\s+(\w+)',src[f],re.M).group(1)
    for m in decl.finditer(src[f]):
        syms.append((os.path.dirname(f),pkgname,m.group(3),bool(m.group(1)),f))

