    tot=0; tot_nt=0; files=set()
    for f in gofiles:
        c=0
        if ismeth:
            c=len(pat.findall(src[f]))
        else:
            if os.path.dirname(f)==pkgdir:
                c=len(re.findall(r'(?<![\w.])'+re.escape(name)+r'\s*\(',src[f]))
